target.echoxml:
[{
    "type": "${ext.package}.${ext.class}",
    "name": "SRCMySQL",
    "external": "true",
    "categoryString": "EXTENSION",
    "helpString": "SRC MySQL Pro Extension v2.0 - Secure MySQL for Android Apps. Made by Shree Ram Computers, Daurala, Meerut. Better than Deep Host: HMAC Auth, Session Tokens, Pagination.",
    "showOnPalette": "true",
    "nonVisible": "true",
    "iconName": "aiwebres/icon.png",
    "androidMinSdk": 7,
    "version": "${ext.version}",
    "versionName": "2.0.0",
    "dateBuilt": "${TODAY}",
    "events": [
        {
            "name": "OnSuccess",
            "description": "Fired when request succeeds.",
            "params": [
                {"name":"callId","type":"text"},
                {"name":"data","type":"text"},
                {"name":"rowCount","type":"number"}
            ]
        },
        {
            "name": "OnError",
            "description": "Fired when request fails.",
            "params": [
                {"name":"callId","type":"text"},
                {"name":"error","type":"text"}
            ]
        },
        {
            "name": "OnAuthenticated",
            "description": "Fired when authentication succeeds.",
            "params": [
                {"name":"sessionToken","type":"text"},
                {"name":"expiresInSeconds","type":"number"}
            ]
        }
    ],
    "properties": [
        {
            "name": "ServerUrl",
            "editorType": "string",
            "defaultValue": ""
        },
        {
            "name": "SecretKey",
            "editorType": "string",
            "defaultValue": ""
        },
        {
            "name": "DebugMode",
            "editorType": "boolean",
            "defaultValue": "false"
        },
        {
            "name": "ConnectTimeoutSeconds",
            "editorType": "integer",
            "defaultValue": "15"
        }
    ]
}]
